// src/app/ratgeber/page.js

import Link from "next/link";
import { ArrowUpRight, BookOpen, Calculator, Coins, HelpCircle, Map as KarteIcon, Scale, Sprout, Zap } from "lucide-react";

import PageHero from "@/components/ui/PageHero";
import Section from "@/components/ui/Section";
import SectionHeading from "@/components/ui/SectionHeading";
import FeatureGrid from "@/components/ui/FeatureGrid";
import CtaBand from "@/components/ui/CtaBand";
import Reveal from "@/components/ui/Reveal";
import { ArtikelKarte } from "@/components/Ratgeber/Bausteine";
import RatgeberListe from "@/components/Ratgeber/RatgeberListe";
import { KATEGORIEN, alleArtikel, artikelPfad } from "@/lib/ratgeber";
import { BEGRIFFE } from "@/data/lexikon";
import { AGRI, KOMMUNE, PACHT, PROVISION, STAND } from "@/lib/invest/markt";
import { fmt } from "@/lib/rechner/annahmen";
import { SITE, abs } from "@/data/site";

const KATEGORIE_ICONS = {
  "Fläche & Pacht": KarteIcon,
  "Agri-PV & Landwirtschaft": Sprout,
  "Investieren & Projektbörse": Coins,
  "Recht & Genehmigung": Scale,
  "Strom, Markt & Gemeinschaft": Zap,
};

const PAGE_URL = abs("/ratgeber");

const TITEL = "Ratgeber Solarpark, Agri-PV & Pacht 2026 | ÖkoInvest";
const DESCRIPTION =
  "Fachwissen für Flächeneigentümer, Landwirte und Investoren: Pacht, Agri-PV, Genehmigung, Projektrechte, PPA und Energiegemeinschaften in DE, AT und CH.";

export const metadata = {
  title: TITEL,
  description: DESCRIPTION,
  keywords: ["Solarpark Ratgeber", "Solarpark Pacht", "Agri-PV", "Freiflächen-PV Genehmigung", "Projektrechte kaufen", "PPA Unternehmen", "Energiegemeinschaft"],
  alternates: { canonical: PAGE_URL },
  robots: { index: true, follow: true },
  openGraph: {
    type: "website",
    url: PAGE_URL,
    siteName: "ÖkoInvest",
    locale: "de_DE",
    title: "Ratgeber: Solarpark, Agri-PV, Pacht & Investment | ÖkoInvest",
    description: DESCRIPTION,
    images: [{ url: abs("/img/solarpark-himmel.jpg"), alt: "Solarpark unter blauem Himmel" }],
  },
};

// Redaktionell empfohlene Artikel (suchstärkste Themen); Fallback: neueste
const EMPFOHLEN = ["solarpark-pacht-pro-hektar", "agri-pv-wirtschaftlichkeit", "projektrechte-kaufen-due-diligence"];

export default function RatgeberPage() {
  const artikel = alleArtikel();
  const empfohlen = EMPFOHLEN.map((s) => artikel.find((a) => a.slug === s)).filter(Boolean);
  const [top, ...rest] = empfohlen.length === EMPFOHLEN.length ? empfohlen : artikel;
  const vorhanden = new Set(artikel.map((a) => a.slug));
  const ratgeberOder = (slug, ersatz) => (vorhanden.has(slug) ? artikelPfad(slug) : ersatz);

  const jsonLd = {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "CollectionPage",
        "@id": `${PAGE_URL}/#collection`,
        url: PAGE_URL,
        name: "ÖkoInvest-Ratgeber",
        description: DESCRIPTION,
        inLanguage: "de",
        isPartOf: { "@id": `${SITE.url}/#website` },
        publisher: { "@id": `${SITE.url}/#organization` },
        mainEntity: { "@id": `${PAGE_URL}/#list` },
      },
      {
        "@type": "ItemList",
        "@id": `${PAGE_URL}/#list`,
        itemListElement: artikel.map((a, i) => ({
          "@type": "ListItem",
          position: i + 1,
          name: a.title,
          url: abs(artikelPfad(a.slug)),
        })),
      },
    ],
  };

  // Zitierfähige Kennzahlen – alle aus src/lib/invest/markt.js.
  const fakten = [
    {
      wert: `${fmt(PACHT.freiflaecheProHa.min)}–${fmt(PACHT.freiflaecheProHa.max)} €`,
      text: "Pacht je Hektar und Jahr für Freiflächen-PV – ein Vielfaches der üblichen Ackerpacht",
      href: ratgeberOder("solarpark-pacht-pro-hektar", "/flaeche-verpachten"),
    },
    {
      wert: `${fmt(AGRI.gapFoerderfaehig * 100)} %`,
      text: "der Fläche einer Agri-PV-Anlage bleiben in Deutschland für GAP-Direktzahlungen förderfähig",
      href: ratgeberOder("agri-pv-foerderung-gap", "/agri-pv"),
    },
    {
      wert: `${fmt(KOMMUNE.beteiligungCt, 1)} ct`,
      text: "je kWh dürfen Betreiber nach § 6 EEG freiwillig an die Standortgemeinden zahlen",
      href: ratgeberOder("solarpark-genehmigung-bebauungsplan", "/kommunen"),
    },
    {
      wert: `${fmt(PROVISION.verkaeufer.min * 100, 1)}–${fmt(PROVISION.verkaeufer.max * 100)} %`,
      text: "Verkäuferprovision in der Projektbörse – nur bei Abschluss, für Investoren kostenfrei",
      href: ratgeberOder("projektrechte-kaufen-due-diligence", "/projektboerse"),
    },
  ];

  return (
    <>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd).replace(/</g, "\\u003c") }} />

      <PageHero
        variant="dark"
        breadcrumbs={[{ name: "Ratgeber" }]}
        eyebrow={`Wissen aus der Projektentwicklung · Stand ${STAND}`}
        title={
          <>
            Ratgeber für <span className="ov-text-gradient-light">Fläche, Projekt und Kapital</span>
          </>
        }
        lead="Was bringt eine Fläche an Pacht, wie läuft ein Bebauungsplan, was ist ein Projekt in welcher Phase wert und wie funktionieren PPA und Energiegemeinschaften? Fachartikel für Deutschland, Österreich und die Schweiz – mit Quellen, Rechenbeispielen und ehrlichen Grenzen."
        stats={[
          { value: artikel.length, label: "Fachartikel" },
          { value: BEGRIFFE.length, label: "Begriffe im Lexikon" },
          { value: 3, label: "Märkte: DE, AT, CH" },
        ]}
      />

      <Section tone="sand" space="lg">
        <SectionHeading eyebrow="Themenbereiche" title="Wählen Sie Ihr Thema" className="mb-10" />
        <ul className="grid gap-4 sm:grid-cols-2 lg:grid-cols-5">
          {KATEGORIEN.map((k, i) => {
            const liste = artikel.filter((a) => a.kategorie === k);
            const Icon = KATEGORIE_ICONS[k] || BookOpen;
            return (
              <Reveal as="li" key={k} delay={i * 60} className="flex">
                <div className="flex w-full flex-col rounded-3xl bg-white p-6 ring-1 ring-ink-200/60">
                  <span className="flex h-11 w-11 items-center justify-center rounded-2xl bg-ov-50 text-ov-600">
                    <Icon aria-hidden="true" className="h-5 w-5" />
                  </span>
                  <h3 className="mt-5 font-display text-[17px] font-bold leading-snug text-ink-900">{k}</h3>
                  <p className="mt-1 text-[13.5px] text-ink-500">{liste.length} Artikel</p>
                  <ul className="mt-4 space-y-2 text-[14px]">
                    {liste.slice(0, 4).map((a) => (
                      <li key={a.slug}>
                        <Link href={artikelPfad(a.slug)} className="text-ink-700 underline-offset-2 hover:text-ov-700 hover:underline">
                          {a.kurzTitel || a.title}
                        </Link>
                      </li>
                    ))}
                  </ul>
                </div>
              </Reveal>
            );
          })}
        </ul>

        {top && (
          <div className="mt-14">
            <SectionHeading eyebrow="Empfohlen" title="Hier fangen die meisten an" className="mb-8" />
            <div className="grid gap-5 lg:grid-cols-[1.35fr_1fr]">
              <ArtikelKarte artikel={top} gross />
              <div className="grid gap-5 sm:grid-cols-2 lg:grid-cols-1">
                {rest.slice(0, 2).map((a, i) => (
                  <ArtikelKarte key={a.slug} artikel={a} delay={(i + 1) * 90} />
                ))}
              </div>
            </div>
          </div>
        )}
      </Section>

      <Section tone="white" space="lg" id="alle-artikel">
        <SectionHeading eyebrow="Alle Ratgeber" title="Alle Artikel durchsuchen" className="mb-10" />
        <RatgeberListe
          kategorien={KATEGORIEN}
          artikel={artikel.map(({ slug, title, excerpt, kategorie, bild, bildAlt, lesezeit, keywords }) => ({ slug, title, excerpt, kategorie, bild, bildAlt, lesezeit, keywords: keywords || [] }))}
        />
      </Section>

      <Section tone="navy" space="lg" className="overflow-hidden">
        <div aria-hidden="true" className="ov-grid-bg absolute inset-0" />
        <div aria-hidden="true" className="absolute -right-32 top-0 h-[420px] w-[420px] rounded-full bg-ov-500/20 blur-[130px]" />
        <div className="relative">
          <SectionHeading dark eyebrow="Mehr Wissen" title="Kurz nachschlagen oder selbst rechnen" className="mb-12" />
          <FeatureGrid
            tone="dark"
            cols={3}
            items={[
              { icon: BookOpen, title: "Lexikon", text: `${BEGRIFFE.length} Fachbegriffe von Aufstellungsbeschluss bis Zuschlagswert – jeweils mit Definition in einem Satz.`, href: "/wissen/lexikon" },
              { icon: Calculator, title: "Rechner", text: "Pacht, Agri-PV, Solarpark, Projektbewertung und Reststrom – mit denselben Marktannahmen wie in den Artikeln.", href: "/rechner" },
              { icon: HelpCircle, title: "Häufige Fragen", text: "Kurze Antworten zu Flächencheck, Projektbörse, Portal, Provision und Ablauf.", href: "/faq" },
            ]}
          />
        </div>
      </Section>

      <Section tone="white" space="lg">
        <div className="grid gap-12 lg:grid-cols-[0.8fr_1.2fr] lg:gap-20">
          <SectionHeading
            eyebrow="Auf einen Blick"
            title="Zahlen, die Sie kennen sollten"
            lead={`Richtwerte aus unseren Ratgebern und Rechnern, Stand ${STAND} – mit der ausführlichen Erklärung verlinkt.`}
          />
          <ul className="grid gap-4 sm:grid-cols-2">
            {fakten.map((f, i) => (
              <Reveal as="li" key={f.text} delay={i * 70} className="flex">
                <Link href={f.href} className="group ov-card-hover relative flex w-full flex-col rounded-3xl bg-sand-50 p-6 ring-1 ring-ink-200/60 hover:bg-white hover:ring-ov-200 md:p-7">
                  <ArrowUpRight aria-hidden="true" className="absolute right-5 top-5 h-5 w-5 text-ink-300 transition-all group-hover:-translate-y-0.5 group-hover:translate-x-0.5 group-hover:text-ov-600" />
                  <span className="ov-num pr-6 font-display text-[clamp(1.7rem,1.4rem+1vw,2.4rem)] font-extrabold leading-none tracking-tight text-ink-900">{f.wert}</span>
                  <span className="mt-3 text-[15px] leading-relaxed text-ink-600">{f.text}</span>
                </Link>
              </Reveal>
            ))}
          </ul>
        </div>
      </Section>

      <CtaBand
        eyebrow="Vom Lesen zum Projekt"
        title="Genug gelesen? Wir prüfen Ihre Fläche oder Ihr Projekt konkret."
        text="Aus Richtwerten wird eine Einschätzung: Netzanschluss, Planungsrecht, Flächenkulisse und Wirtschaftlichkeit – kostenfrei für Flächeneigentümer und Investoren."
      />
    </>
  );
}
"use client";

import { useMemo, useState } from "react";
import Image from "next/image";
import Link from "next/link";
import { ArrowRight, Clock, Search, X } from "lucide-react";

/**
 * Filterbare Artikelliste der Ratgeber-Übersicht.
 * Bekommt nur schlanke Metadaten (keine Artikelinhalte), damit das
 * Client-Bundle klein bleibt. Alle Karten stehen im Server-HTML – Filter und
 * Suche blenden nur aus, Links bleiben für Suchmaschinen auffindbar.
 */
export default function RatgeberListe({ artikel, kategorien }) {
  const [kategorie, setKategorie] = useState("Alle");
  const [suche, setSuche] = useState("");

  const zaehler = useMemo(() => {
    const z = { Alle: artikel.length };
    for (const a of artikel) z[a.kategorie] = (z[a.kategorie] || 0) + 1;
    return z;
  }, [artikel]);

  const sichtbar = useMemo(() => {
    const q = suche.trim().toLowerCase();
    return new Set(
      artikel
        .filter((a) => kategorie === "Alle" || a.kategorie === kategorie)
        .filter((a) => !q || `${a.title} ${a.excerpt} ${a.keywords.join(" ")}`.toLowerCase().includes(q))
        .map((a) => a.slug)
    );
  }, [artikel, kategorie, suche]);

  return (
    <div>
      <div className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
        <div role="group" aria-label="Nach Thema filtern" className="ov-no-scrollbar -mx-5 flex gap-2 overflow-x-auto px-5 pb-1 lg:mx-0 lg:flex-wrap lg:px-0">
          {["Alle", ...kategorien].map((k) => {
            const aktiv = kategorie === k;
            return (
              <button
                key={k}
                type="button"
                aria-pressed={aktiv}
                onClick={() => setKategorie(k)}
                className={`inline-flex h-11 shrink-0 items-center gap-2 whitespace-nowrap rounded-full px-4 text-[14px] font-semibold transition-all ${
                  aktiv ? "bg-ink-900 text-white shadow-md" : "bg-white text-ink-700 ring-1 ring-ink-200 hover:ring-ink-300"
                }`}
              >
                {k}
                <span className={`ov-num rounded-full px-1.5 text-[12px] ${aktiv ? "bg-white/15 text-white" : "bg-ink-100 text-ink-600"}`}>{zaehler[k] || 0}</span>
              </button>
            );
          })}
        </div>
        <label className="relative block w-full lg:max-w-xs">
          <span className="sr-only">Ratgeber durchsuchen</span>
          <Search aria-hidden="true" className="pointer-events-none absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-ink-400" />
          <input
            type="search"
            value={suche}
            onChange={(e) => setSuche(e.target.value)}
            placeholder="Thema suchen, z. B. Pacht"
            className="h-11 w-full rounded-full border-2 border-ink-200 bg-white pl-11 pr-10 text-[15px] text-ink-900 outline-none placeholder:text-ink-500 focus:border-ov-500"
          />
          {suche && (
            <button type="button" onClick={() => setSuche("")} aria-label="Suche leeren" className="absolute right-3 top-1/2 flex h-7 w-7 -translate-y-1/2 items-center justify-center rounded-full text-ink-400 hover:bg-ink-100">
              <X aria-hidden="true" className="h-4 w-4" />
            </button>
          )}
        </label>
      </div>

      <p aria-live="polite" className="mt-5 text-[14px] text-ink-500">
        {sichtbar.size === artikel.length ? `${artikel.length} Artikel` : `${sichtbar.size} von ${artikel.length} Artikeln`}
      </p>

      <ul className="mt-6 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
        {artikel.map((a) => (
          <li key={a.slug} hidden={!sichtbar.has(a.slug)} className="flex">
            <Karte a={a} />
          </li>
        ))}
      </ul>

      {sichtbar.size === 0 && (
        <div className="mt-6 rounded-3xl bg-white p-8 text-center ring-1 ring-ink-200/70">
          <p className="font-display text-[18px] font-bold text-ink-900">Kein Artikel gefunden.</p>
          <p className="mt-2 text-[15px] text-ink-600">
            Versuchen Sie einen anderen Begriff – oder schauen Sie ins <Link href="/wissen/lexikon" className="font-semibold text-ov-700 underline">Lexikon</Link>.
          </p>
        </div>
      )}
    </div>
  );
}

function Karte({ a }) {
  return (
    <article className="group ov-card-hover relative flex w-full flex-col rounded-3xl bg-white ring-1 ring-ink-200/70 focus-within:ring-2 focus-within:ring-ov-500 hover:ring-ov-200">
      <div className="relative aspect-[16/9] overflow-hidden rounded-t-3xl bg-ink-100">
        <Image src={a.bild} alt={a.bildAlt} fill sizes="(max-width: 640px) 100vw, (max-width: 1024px) 50vw, 33vw" className="object-cover transition-transform duration-700 group-hover:scale-105" />
        <span className="absolute left-4 top-4 rounded-full bg-white/95 px-3 py-1 text-[12px] font-semibold text-ink-800 shadow-sm backdrop-blur">{a.kategorie}</span>
      </div>
      <div className="flex flex-1 flex-col p-6">
        <h3 className="font-display text-[18.5px] font-extrabold leading-snug tracking-tight text-ink-900 transition-colors group-hover:text-ov-700">
          <Link href={`/ratgeber/${a.slug}`} className="outline-none after:absolute after:inset-0 after:content-['']">
            {a.title}
          </Link>
        </h3>
        <p className="mt-3 line-clamp-3 text-[15px] leading-relaxed text-ink-600">{a.excerpt}</p>
        <div className="mt-auto flex items-center justify-between gap-4 pt-6 text-[13px] text-ink-500">
          <span className="flex items-center gap-1.5">
            <Clock aria-hidden="true" className="h-3.5 w-3.5" />
            {a.lesezeit} Min. Lesezeit
          </span>
          <span aria-hidden="true" className="flex h-9 w-9 items-center justify-center rounded-full bg-ink-100 text-ink-600 transition-all group-hover:bg-ov-500 group-hover:text-white">
            <ArrowRight className="h-4 w-4 transition-transform group-hover:translate-x-0.5" />
          </span>
        </div>
      </div>
    </article>
  );
}

// src/app/wissen/lexikon/page.js

import Link from "next/link";
import { ArrowDown, BookOpen, Calculator, HelpCircle } from "lucide-react";

import PageHero from "@/components/ui/PageHero";
import Section from "@/components/ui/Section";
import SectionHeading from "@/components/ui/SectionHeading";
import FeatureGrid from "@/components/ui/FeatureGrid";
import CtaBand from "@/components/ui/CtaBand";
import Querverweise from "@/components/Reusable/Querverweise";
import LexikonExplorer from "@/components/Lexikon/LexikonExplorer";
import { BEGRIFFE, KATEGORIEN, LEXIKON_STAND, begriffeNachBuchstabe, buchstabeVon } from "@/data/lexikon";
import { SITE, abs } from "@/data/site";

const PAGE_URL = abs("/wissen/lexikon");
const ANZAHL = BEGRIFFE.length;

const TITLE = `Lexikon Solarpark & Agri-PV: ${ANZAHL} Begriffe | ÖkoInvest`;
const DESCRIPTION = `${ANZAHL} Fachbegriffe aus Projektentwicklung, Genehmigung, Strommarkt und Investment – von Aufstellungsbeschluss über PPA bis Zuschlagswert, für DE, AT und CH.`;

export const metadata = {
  title: TITLE,
  description: DESCRIPTION,
  keywords: ["Solarpark Lexikon", "Agri-PV Begriffe", "Photovoltaik Glossar Freifläche", "Projektrechte", "Ready-to-Build", "PPA Definition", "Energy Sharing"],
  alternates: { canonical: PAGE_URL },
  robots: { index: true, follow: true },
  openGraph: {
    type: "website",
    url: PAGE_URL,
    siteName: "ÖkoInvest",
    locale: "de_DE",
    title: `Lexikon: ${ANZAHL} Fachbegriffe zu Solarpark, Agri-PV und Strommarkt`,
    description: DESCRIPTION,
    images: [{ url: abs("/img/solarpark-reihen.jpg"), alt: "Modulreihen eines Solarparks" }],
  },
};

const BELIEBT = ["aufstellungsbeschluss", "dienstbarkeit", "din-spec-91434", "rtb", "ppa", "capture-rate", "energy-sharing"];
const FOKUS = "projektrechte";

export default function LexikonPage() {
  const gruppen = begriffeNachBuchstabe();
  const namen = Object.fromEntries(BEGRIFFE.map((b) => [b.id, b.begriff]));
  const beliebt = BELIEBT.filter((id) => namen[id]);
  const fokus = BEGRIFFE.find((b) => b.id === FOKUS);

  const jsonLd = {
    "@context": "https://schema.org",
    "@graph": [
      {
        "@type": "WebPage",
        "@id": `${PAGE_URL}/#webpage`,
        url: PAGE_URL,
        name: TITLE,
        description: DESCRIPTION,
        inLanguage: "de",
        isPartOf: { "@id": `${SITE.url}/#website` },
        publisher: { "@id": `${SITE.url}/#organization` },
        dateModified: LEXIKON_STAND,
        mainEntity: { "@id": `${PAGE_URL}/#termset` },
      },
      {
        "@type": "DefinedTermSet",
        "@id": `${PAGE_URL}/#termset`,
        name: "ÖkoInvest-Lexikon",
        description: "Fachbegriffe zu Freiflächen-PV, Agri-PV, Genehmigung, Netzanschluss, Strommarkt, Projekttransaktionen und Energiegemeinschaften in Deutschland, Österreich und der Schweiz.",
        url: PAGE_URL,
        inLanguage: "de",
        publisher: { "@id": `${SITE.url}/#organization` },
        hasDefinedTerm: BEGRIFFE.map((b) => ({
          "@type": "DefinedTerm",
          "@id": `${PAGE_URL}#${b.id}`,
          name: b.begriff,
          description: b.kurz,
          url: `${PAGE_URL}#${b.id}`,
          ...(b.synonyme?.length ? { alternateName: b.synonyme } : {}),
          inDefinedTermSet: { "@id": `${PAGE_URL}/#termset` },
        })),
      },
    ],
  };

  return (
    <>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd).replace(/</g, "\\u003c") }} />

      <PageHero
        variant="dark"
        breadcrumbs={[{ name: "Ratgeber", href: "/ratgeber" }, { name: "Lexikon" }]}
        eyebrow="Wissen · Stand September 2026"
        title={
          <>
            Lexikon: <span className="ov-text-gradient-light">Fachbegriffe</span> von A bis Z
          </>
        }
        lead="Von Aufstellungsbeschluss bis Zuschlagswert: die Begriffe aus Pachtvertrag, Bebauungsplan, Netzanschluss, Ausschreibung und Projektkauf – jeweils mit einer Definition in einem Satz, einer Erklärung für Deutschland, Österreich und die Schweiz und dem Weg zum passenden Rechner."
        stats={[
          { value: ANZAHL, label: "Fachbegriffe erklärt" },
          { value: KATEGORIEN.length, label: "Themenfelder" },
          { value: new Set(BEGRIFFE.filter((b) => b.link).map((b) => b.link.href.split("#")[0])).size, label: "verlinkte Rechner & Seiten" },
        ]}
      >
        {fokus && (
          <aside
            aria-label="Begriff im Fokus"
            className="ov-hero-in absolute top-[200px] hidden w-[380px] xl:block"
            style={{ "--ov-delay": "300ms", right: "max(2rem, calc((100vw - 80rem) / 2 + 2rem))" }}
          >
            <div aria-hidden="true" className="absolute -inset-6 rounded-[2.5rem] bg-ov-500/20 blur-3xl" />
            <div className="ov-glass relative rounded-[2rem] p-7">
              <div className="flex items-center justify-between">
                <p className="text-[12px] font-semibold uppercase tracking-[0.16em] text-ov-300">Begriff im Fokus</p>
                <span aria-hidden="true" className="font-display text-[56px] font-extrabold leading-none text-white/10">{buchstabeVon(fokus)}</span>
              </div>
              <p className="-mt-3 font-display text-[26px] font-extrabold tracking-tight text-white">{fokus.begriff}</p>
              <p className="mt-3 text-[15px] leading-relaxed text-white/75">{fokus.kurz}</p>
              <a href={`#${fokus.id}`} className="mt-5 inline-flex items-center gap-2 text-[14px] font-semibold text-ov-300 hover:text-white">
                Ganze Erklärung lesen
