// Rendert alle inhaltsgetriebenen Ratgeber-Artikel aus src/content/ratgeber.

import { notFound } from "next/navigation";
import { BookOpen } from "lucide-react";

import ArtikelLayout from "@/components/Ratgeber/ArtikelLayout";
import ArtikelInhalt from "@/components/Ratgeber/ArtikelInhalt";
import { klartext } from "@/components/Ratgeber/InlineText";
import { INHALTS_ARTIKEL, artikelPfad } from "@/lib/ratgeber";
import { SITE, abs } from "@/data/site";

const BASE_URL = SITE.url;

export const dynamicParams = false;

export function generateStaticParams() {
  return INHALTS_ARTIKEL.map((a) => ({ slug: a.slug }));
}

const finde = (slug) => INHALTS_ARTIKEL.find((a) => a.slug === slug);

export async function generateMetadata({ params }) {
  const { slug } = await params;
  const a = finde(slug);
  if (!a) return {};
  const url = abs(artikelPfad(a.slug));
  const bild = abs(a.bild);
  return {
    title: a.seoTitle || `${a.kurzTitel || a.title} | ÖkoInvest`,
    description: a.description,
    keywords: a.keywords,
    alternates: { canonical: url },
    robots: { index: true, follow: true, googleBot: { index: true, follow: true, "max-image-preview": "large", "max-snippet": -1 } },
    openGraph: {
      type: "article",
      url,
      siteName: "ÖkoInvest",
      locale: "de_DE",
      title: a.title,
      description: a.description,
      publishedTime: a.veroeffentlicht,
      modifiedTime: a.aktualisiert,
      section: a.kategorie,
      images: [{ url: bild, alt: a.bildAlt }],
    },
    twitter: { card: "summary_large_image", title: a.title, description: a.description, images: [bild] },
  };
}

export default async function RatgeberArtikelPage({ params }) {
  const { slug } = await params;
  const a = finde(slug);
  if (!a) notFound();

  const url = abs(artikelPfad(a.slug));

  const toc = [
    ...(a.kurzFazit?.length ? [{ id: "kurz", label: "Das Wichtigste in Kürze" }] : []),
    ...a.abschnitte.map((s) => ({ id: s.id, label: s.tocLabel || s.titel })),
    ...(a.faq?.length ? [{ id: "faq", label: "Häufige Fragen" }] : []),
  ];

  const graph = [
    {
      "@type": "Article",
      "@id": `${url}/#article`,
      headline: a.title,
      description: a.description,
      inLanguage: "de-DE",
      datePublished: a.veroeffentlicht,
      dateModified: a.aktualisiert,
      author: { "@type": "Organization", name: "Projektteam ÖkoInvest", "@id": `${BASE_URL}/#organization` },
      publisher: { "@id": `${BASE_URL}/#organization` },
      mainEntityOfPage: { "@type": "WebPage", "@id": url },
      image: [abs(a.bild)],
      articleSection: a.kategorie,
      keywords: (a.keywords || []).join(", "),
      wordCount: a.woerter,
      timeRequired: `PT${a.lesezeit}M`,
      abstract: (a.kurzFazit || []).map(klartext).join(" "),
      ...(a.quellen?.length ? { citation: a.quellen.map((q) => ({ "@type": "CreativeWork", name: q.titel, url: q.url })) } : {}),
    },
  ];

  if (a.howTo?.schritte?.length) {
    graph.push({
      "@type": "HowTo",
      "@id": `${url}/#howto`,
      name: a.howTo.name,
      inLanguage: "de-DE",
      step: a.howTo.schritte.map((s, i) => ({ "@type": "HowToStep", position: i + 1, name: s.name, text: klartext(s.text) })),
    });
  }

  return (
    <>
      <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify({ "@context": "https://schema.org", "@graph": graph }).replace(/</g, "\\u003c") }} />
      <ArtikelLayout
        artikel={a}
        toc={toc}
        badge={
          a.badge && (
            <div className="flex items-center gap-4">
              <span className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-ov-500 text-white">
                <BookOpen aria-hidden="true" className="h-6 w-6" />
              </span>
              <div>
                <p className="ov-num font-display text-[22px] font-extrabold leading-none text-ink-900">{a.badge.wert}</p>
                <p className="mt-1 text-[12.5px] leading-snug text-ink-500">{a.badge.text}</p>
              </div>
            </div>
          )
        }
        seitenCta={a.seitenCta}
        cta={a.cta}
      >
        <ArtikelInhalt artikel={a} />
      </ArtikelLayout>
    </>
  );
}
import { Calculator } from "lucide-react";

import PageHero from "@/components/ui/PageHero";
import Section from "@/components/ui/Section";
import SectionHeading from "@/components/ui/SectionHeading";
import CtaBand from "@/components/ui/CtaBand";
import Button from "@/components/ui/Button";
import ReadingProgress from "./ReadingProgress";
import TableOfContents from "./TableOfContents";
import Teilen from "@/components/ui/Teilen";
import { artikelPfad } from "@/lib/ratgeber";
import { abs } from "@/data/site";
import { ArtikelMeta, Autorenbox, WeitereArtikel } from "./Bausteine";

const TEILEN_NETZE = ["whatsapp", "linkedin", "facebook", "xing", "x", "telegram"];

/**
 * Gemeinsames Gerüst aller Ratgeber-Artikel (Magazin-Look):
 * Artikel-Hero mit Autor/Lesezeit → Text mit klebendem Inhaltsverzeichnis
 * → Autorenbox → Weiterlesen → Abschluss-CTA.
 *
 * props:
 *  artikel   Eintrag aus @/lib/ratgeber
 *  toc       [{ id, label }]
 *  titel     h1 (JSX erlaubt)
 *  badge     JSX – schwebende Kennzahl auf dem Hero-Bild
 *  seitenCta { titel, text, href, label } – Karte unter dem Inhaltsverzeichnis
 *  cta       Props für <CtaBand/>
 */
export default function ArtikelLayout({ artikel, toc, titel, badge, seitenCta, cta = {}, children }) {
  const url = abs(artikelPfad(artikel.slug));
  const teilenText = artikel.excerpt || artikel.description;

  return (
    <>
      <ReadingProgress />

      <PageHero
        breadcrumbs={[{ name: "Ratgeber", href: "/ratgeber" }, { name: artikel.kurzTitel }]}
        eyebrow={artikel.kategorie}
        title={titel || artikel.title}
        lead={artikel.excerpt}
        image={{ src: artikel.bild, alt: artikel.bildAlt }}
        badge={badge}
      >
        <ArtikelMeta artikel={artikel} />
      </PageHero>

      <Section tone="white" space="none" className="pb-16 pt-10 md:pb-24 md:pt-16">
        <div className="grid gap-12 lg:grid-cols-[minmax(0,1fr)_270px] lg:gap-14 xl:gap-20">
          <article className="min-w-0">
            <TableOfContents items={toc} variant="mobile" />
            <div className="max-w-[52rem]">
              {children}
              <div className="mt-14 flex flex-col gap-3 rounded-3xl border border-ink-200 p-5 sm:flex-row sm:items-center sm:justify-between md:p-6">
                <p className="font-display text-[17px] font-bold text-ink-900">Hilfreich? Teilen Sie den Artikel.</p>
                <Teilen url={url} titel={artikel.title} text={teilenText} netze={TEILEN_NETZE} kampagne="ratgeber" kompakt />
              </div>
              <Autorenbox artikel={artikel} />
            </div>
          </article>

          {/* kein <aside>: Seitenleiste liegt innerhalb des Hauptinhalts (landmark-complementary-is-top-level) */}
          <div className="hidden lg:block">
            <div className="sticky top-28 space-y-6">
              <TableOfContents items={toc} variant="desktop" />
